fn visual_onehome(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let p = uv * 0.5 + vec2f(0.5, 0.5);
  var col = mix(vec3f(0.015, 0.018, 0.045), vec3f(0.05, 0.03, 0.09), p.y);
  for (var l: i32 = 0; l < 3; l = l + 1) {
    let lf = f32(l);
    let sc = 18.0 + lf * 26.0;
    let g = (p + vec2f(time * (0.004 + lf * 0.006), 0.0)) * sc;
    let cell = floor(g);
    let h = fract(sin(dot(cell, vec2f(127.1, 311.7))) * 43758.5453);
    let star = smoothstep(0.985 - lf * 0.004, 1.0, h);
    let tw = 0.6 + 0.4 * sin(time * (1.0 + h * 3.0) + h * 40.0);
    col += vec3f(0.9, 0.85, 1.0) * star * tw * (0.25 + lf * 0.2);
  }
  let dd = distance(p, vec2f(0.5, 0.85));
  col += vec3f(0.45, 0.25, 0.08) * exp(-dd * dd * 9.0) * 0.35;
  return vec4f(col, 1.0);
}
